}

.block-back { border-left: 4px solid #ffcc00; }
.back-content { font-size: 17px; color: #3a3a3c; }

.block-audio {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    border-left: 4px solid #34c759;
}

.block-link {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
}
.block-link:active { background-color: #e5e5ea; transform: scale(0.99); }
.link-wrapper { width: 100%; }
.chevron-right { font-size: 20px; color: #c7c7cc; font-weight: 300; padding-left: 12px; user-select: none; }

.block-label {
    display: block;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #8e8e93;
    margin-bottom: 14px;
    padding-bottom: 6px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.05);
    width: 100%;
}

/* ---------- Thiết Kế Thẻ Cloze Cao Cấp ---------- */
.cloze[data-cloze] {
    font-weight: 600;
    color: #ffffff;
    background-color: #007aff;
    padding: 2px 8px;
    border-radius: 6px;
}

.cloze:not([data-cloze]) {
    font-weight: 600;
    color: #007aff;
    background-color: rgba(0, 122, 255, 0.1);
    padding: 2px 8px;
    border-radius: 6px;
}
.cloze b, .cloze strong { color: inherit; }

/* ---------- Ẩn Ô Nhập Liệu Mặc Định Của Anki ---------- */
.typing-area { display: none !important; }
