    background-color: #007aff;
    padding: 2px 8px;
    border-radius: 6px;
}

.cloze:not([data-cloze]) {
    font-weight: 600;
    color: #007aff;
    background-color: rgba(0, 122, 255, 0.1);
    padding: 2px 8px;
    border-radius: 6px;
}
