/* ===== APPLE PREMIUM MINIMALISM DESIGN (OPTIMIZED) ===== */

/* ---------- Khung Nền Hệ Thống & Font Stack Toàn Diện ---------- */
.card {
    font-family: "SF Pro Text", "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Helvetica, Arial, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
