    align-items: center;
    justify-content: center;
    border-left: 4px solid #34c759;
}

.block-link {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
}
.block-link:active { background-color: #e5e5ea; transform: scale(0.99); }
.link-wrapper { width: 100%; }
.chevron-right { font-size: 20px; color: #c7c7cc; font-weight: 300; padding-left: 12px; user-select: none; }

.block-label {
    display: block;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #8e8e93;
    margin-bottom: 14px;
    padding-bottom: 6px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.05);
    width: 100%;
}

