.nightMode .chevron-right { color: #48484a; }
.nightMode .block-label { border-bottom-color: rgba(255, 255, 255, 0.07); color: #8e8e93; }
.nightMode .cloze[data-cloze] { background-color: #0a84ff; color: #ffffff; }
.nightMode .cloze:not([data-cloze]) { background-color: rgba(10, 132, 255, 0.15); color: #0a84ff; }
.nightMode b, .nightMode strong { color: #ff453a; }
.nightMode u { border-bottom-color: #0a84ff; }

/* Dark Mode cho Input & Hint */
.nightMode .apple-inline-input { color: #f5f5f7; background-color: #2c2c2e; border-color: rgba(255,255,255,0.1); }
.nightMode .apple-inline-input:focus { color: #0a84ff; background-color: #1c1c1e; border-color: #0a84ff; box-shadow: 0 0 0 3px rgba(10, 132, 255, 0.25); }
.nightMode .apple-inline-input.is-correct { color: #30d158 !important; border-color: #30d158 !important; background-color: rgba(48, 209, 88, 0.15) !important; box-shadow: 0 0 0 3px rgba(48, 209, 88, 0.2) !important; }
.nightMode .apple-inline-input.is-incorrect { color: #ff453a !important; border-color: #ff453a !important; background-color: rgba(255, 69, 58, 0.15) !important; box-shadow: 0 0 0 3px rgba(255, 69, 58, 0.2) !important; }

.nightMode .apple-hint-display { background-color: #1c1c1e; }
.nightMode .apple-hint-display .ch.blank { color: #48484a; }
.nightMode .apple-hint-display .ch.symbol { color: #636366; }
.nightMode .apple-hint-display .ch.correct { color: #30d158; }
.nightMode .apple-hint-display .ch.assisted { color: #ff9f0a; }
.nightMode .apple-hint-display .ch.incorrect { color: #ff453a; background-color: rgba(255, 69, 58, 0.15); text-decoration-color: #ff453a; }
.nightMode .apple-hint-display .ch.extra { background-color: rgba(255, 69, 58, 0.2); }
.nightMode .apple-hint-btn { background-color: #2c2c2e; color: #a1a1a6; border-color: rgba(255, 255, 255, 0.1); }
.nightMode .settings-toggle { background-color: #2c2c2e; color: #a1a1a6; }

/* =========================================
   MOBILE RESPONSIVE ACCELERATION
   ========================================= */
@media screen and (max-width: 600px) {
    .card { padding: 16px 8px; }
    .apple-card { padding: 18px 16px; margin-bottom: 12px; border-radius: 14px; }
    .korean-text { font-size: 20px; }
}

/* ---------- Style Ô Gõ Trực Tiếp (Inline Input) ---------- */
.apple-inline-input {
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: inherit;
    font-weight: 600;
    color: #1d1d1f; 
    background-color: #f2f2f7; 
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 8px;
    padding: 2px 8px;
    margin: 0 6px;
    text-align: center;
    outline: none;
    transition: all 0.2s ease;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.02);
    max-width: 100%; 
    box-sizing: border-box;
    text-overflow: ellipsis;
    vertical-align: baseline;
}

/* THÊM ĐOẠN NÀY: Style cho chữ gợi ý (Hint) mờ bên trong ô gõ */
.apple-inline-input::placeholder {
    color: #aeaeb2;
    font-weight: 500;
    font-size: 0.85em;
    opacity: 1;
}
.nightMode .apple-inline-input::placeholder {
    color: #636366;
}
/* --------------------------------------------------------- */

.apple-inline-input:focus {
    color: #007aff; 
    background-color: #ffffff; 
    border-color: #007aff;
    box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.15);
    text-overflow: clip;
}

/* Thêm class này để gom nhóm các chữ cái trong cùng 1 từ */
.word-group {
    display: flex;
    flex-wrap: nowrap; /* Cấm ngắt dòng giữa chừng trong 1 từ */
    gap: 2px;
}

/* ===== FLOATING HINT & SETTINGS MENU (moi) ===== */
.hint-section.floating {
    position: fixed;
    left: 16px;
    right: 16px;
    bottom: 12px;
    z-index: 100;
    margin-top: 0;
    max-height: 40vh;
}
/* khong con khung ngoai cho floating */
body.floating .apple-container { padding-bottom: 110px; }
