    padding: 9px 12px;
    border-radius: 10px;
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: 14px;
    color: #1d1d1f;
    cursor: pointer;
    user-select: none;
}
.settings-menu-item:hover { background: rgba(0, 0, 0, 0.04); }
.settings-menu-item .check { width: 18px; color: #007aff; font-weight: 700; }
