/* ---------- Style Ô Gõ Trực Tiếp (Inline Input) ---------- */
.apple-inline-input {
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: inherit;
    font-weight: 600;
    color: #1d1d1f; 
    background-color: #f2f2f7; 
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 8px;
    padding: 2px 8px;
    margin: 0 6px;
    text-align: center;
    outline: none;
    transition: all 0.2s ease;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.02);
    max-width: 100%; 
    box-sizing: border-box;
    text-overflow: ellipsis;
    vertical-align: baseline;
}

.apple-inline-input:focus {
    color: #007aff; 
    background-color: #ffffff; 
    border-color: #007aff;
    box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.15);
    text-overflow: clip;
}

.apple-inline-input.is-correct {
    color: #248a3d !important;
    border-color: #34c759 !important;
    background-color: rgba(52, 199, 89, 0.15) !important;
    box-shadow: 0 0 0 3px rgba(52, 199, 89, 0.2) !important;
}
.apple-inline-input.is-incorrect {
    color: #ff3b30 !important;
    border-color: #ff3b30 !important;
    background-color: rgba(255, 59, 48, 0.1) !important;
    box-shadow: 0 0 0 3px rgba(255, 59, 48, 0.2) !important;
