/* ---------- Khu Vực Gợi Ý (Hint Section) ---------- */
.hint-section {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 16px;
    transition: opacity 0.3s ease;
}

.apple-hint-display {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 2px;
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: 24px;
    font-weight: 700;
    letter-spacing: 1px;
    margin-bottom: 0;
    min-height: 44px;
    flex: 1 1 auto;
    min-width: 0;
    width: auto;
    padding: 12px 16px;
    background-color: #ffffff;
    border-radius: 14px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    box-sizing: border-box;
}

.apple-hint-display .ch {
    display: inline-block;
    min-width: 0.6em;
    text-align: center;
    padding: 2px 4px;
    border-radius: 6px;
    transition: all 0.15s ease;
}

.apple-hint-display .ch.blank { color: #6e6e73; }
.apple-hint-display .ch.symbol { color: #8e8e93; font-weight: 500; }
.apple-hint-display .ch.correct { color: #34c759; }
.apple-hint-display .ch.assisted { color: #ff9500; }
.apple-hint-display .ch.incorrect { 
    color: #ff3b30; 
    background-color: rgba(255, 59, 48, 0.08);
    text-decoration: underline wavy #ff3b30;
    text-underline-offset: 4px;
}
.apple-hint-display .ch.extra { color: #ff3b30; background-color: rgba(255, 59, 48, 0.15); }
.apple-hint-display .ch.space { min-width: 0.4em; }

.apple-hint-btn {
    position: fixed;
    bottom: 64px;
    right: 20px;
    z-index: 100;
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background-color: #ffffff;
    color: #8e8e93;
    border: 1px solid rgba(0, 0, 0, 0.06);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    font-size: 18px;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
    padding: 0;
    margin: 0;
    transition: all 0.2s ease;
    user-select: none;
}
.apple-hint-btn:active { transform: scale(0.92); background-color: #e5e5ea; }

/* ---------- Nút Cài Đặt (Bật/Tắt Hint) ---------- */
.settings-toggle {
    position: fixed;
    bottom: 20px;
    right: 20px;
    width: 36px;
    height: 36px;
    background-color: #ffffff;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    cursor: pointer;
    color: #8e8e93;
    z-index: 100;
    transition: all 0.2s ease;
}
.settings-toggle:active { transform: scale(0.9); }
.settings-toggle.off { opacity: 0.5; }

