    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 16px;
    transition: opacity 0.3s ease;
}

.apple-hint-display {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 2px;
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: 24px;
