    font-weight: 700;
    line-height: 1;
    cursor: pointer;
    padding: 0;
    margin: 0;
    transition: all 0.2s ease;
    user-select: none;
}
.apple-hint-btn:active { transform: scale(0.92); background-color: #e5e5ea; }

/* ---------- Nút Cài Đặt (Bật/Tắt Hint) ---------- */
.settings-toggle {
    position: fixed;
    bottom: 20px;
    right: 20px;
    width: 36px;
    height: 36px;
    background-color: #ffffff;
    border-radius: 50%;
    display: flex;
