    align-items: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    cursor: pointer;
    color: #8e8e93;
    z-index: 100;
    transition: all 0.2s ease;
}
.settings-toggle:active { transform: scale(0.9); }
.settings-toggle.off { opacity: 0.5; }

