}
.settings-align-box {
    padding: 8px 10px 10px;
    margin: 4px 0;
    border-top: 1px solid rgba(0, 0, 0, 0.06);
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}
.settings-align-label {
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: 11px;
    font-weight: 700;
    color: #8e8e93;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
    user-select: none;
    cursor: pointer;
}
.settings-align-label:hover {
    color: #007aff;
}
.settings-align-options {
    display: flex;
    background: #f2f2f7;
    border-radius: 9px;
    padding: 3px;
    gap: 3px;
}
.align-btn {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 6px 0;
    border: none;
    background: transparent;
    color: #6e6e73;
    border-radius: 7px;
    font-family: "SF Pro Text", "Segoe UI", sans-serif;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    user-select: none;
    outline: none;
}
.align-btn svg {
    display: inline-block;
    vertical-align: middle;
}
.align-btn:hover {
    color: #1d1d1f;
}
.align-btn:active {
    transform: scale(0.96);
}
.align-btn.active {
    background: #007aff;
    color: #ffffff;
    box-shadow: 0 1px 4px rgba(0, 122, 255, 0.35);
}

/* Dark mode cho căn lề */
.nightMode .settings-align-box {
    border-top-color: rgba(255, 255, 255, 0.08);
    border-bottom-color: rgba(255, 255, 255, 0.08);
}
.nightMode .settings-align-label {
    color: #98989d;
}
.nightMode .settings-align-label:hover {
    color: #0a84ff;
}
.nightMode .settings-align-options {
    background: #1c1c1e;
}
.nightMode .align-btn {
    color: #8e8e93;
}
.nightMode .align-btn:hover {
    color: #f5f5f7;
}
.nightMode .align-btn.active {
    background: #0a84ff;
    color: #ffffff;
    box-shadow: 0 1px 4px rgba(10, 132, 255, 0.45);
}
